<?php
session_start(); if(!isset($_SESSION["user_id"])){header("Location: login.php");exit;} require_once "db.php";
$stmt=$conn->prepare("SELECT o.id,o.quantity,o.status,o.created_at,p.name,p.price,p.emoji FROM orders o JOIN products p ON p.id=o.product_id WHERE o.user_id=? ORDER BY o.id DESC");$stmt->bind_param("i",$_SESSION["user_id"]);$stmt->execute();$orders=$stmt->get_result();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Orders | Cool Cafe</title><link rel="stylesheet" href="style.css"></head><body><header class="navbar"><a class="logo" href="index.php">☕ Cool Cafe</a><nav><a href="menu.php">Menu</a><a href="logout.php">Logout</a></nav></header><main class="container"><h1>My Orders</h1><?php if(isset($_GET["placed"])): ?><p class="success">Your order has been placed!</p><?php endif; ?><div class="orders"><?php if(!$orders->num_rows): ?><p>No orders yet. Visit our <a href="menu.php">menu</a>.</p><?php endif; ?><?php while($o=$orders->fetch_assoc()): ?><article class="order"><h3><?= htmlspecialchars($o["emoji"]." ".$o["name"]) ?></h3><p>Quantity: <?= (int)$o["quantity"] ?> · Total: ₹<?= number_format($o["price"]*$o["quantity"],2) ?></p><p>Status: <strong><?= htmlspecialchars(ucfirst($o["status"])) ?></strong></p><small><?= htmlspecialchars($o["created_at"]) ?></small></small><form method="post" action="delete_order.php" onsubmit="return confirm('Delete this order?');"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><button type="submit">Delete</button></form></article></article><?php endwhile; ?></div></main></body></html>
    